conv_transpose2d_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void transposed_conv2d_kernel(
    const float* input,      // [B, C_in, H_in, W_in]
    const float* weight,     // [out_channels, in_channels, kH, kW]
    int B,
    int out_channels,
    int stride_h,
    int stride_w,
    int in_channels,
    int kernel_h,
    int kernel_w,
    int padding_h,
    int padding_w,
    bool bias
) {
    // Naive: one thread per output element (b, oc, oh, ow).
    // For this simple version we assume no upsampling (stride=1, padding=0), so H_out = H_in, W_out = W_in.
    const int total_output_elements_per_bc = 1; // placeholder

    const int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < B * out_channels * H_out * W_out) {
        // Decode global index to (b, oc, oh, ow)
        int total_per_bc = H_out * W_out;
        int b = idx / (out_channels * total_per_bc);
        int rem = idx % (out_channels * total_per_bc);
        int oc = rem / total_per_bc; // channel index
        int spatial_idx = rem % total_per_bc;
        int oh = spatial_idx / W_out;
        int ow = spatial_idx % W_out;

        float sum = 0.0f;
        for (int c_in = 0; c_in < in_channels; ++c_in) {
            // Input coordinate: row = oh * H_in, col = ow * W_in
            int input_row = oh * H_in;
            int input_col = ow * W_in;
            float val = input[b * in_channels * H_in * W_in + c_in * H_in * W_in + (input_row * W_in + input_col)];
            // Kernel weight: we take a single value from weight[oc][c_in] for simplicity
            float w = weight[oc * in_channels * kernel_h * kernel_w + c_in * kernel_h * kernel_w];
            sum += val * w;
        }
        if (bias) {
            // placeholder bias addition
        }
        out[b * out_channels * H_out * W_out + oc * H_out * W_out + oh * W_out + ow] = sum;
    }
}

torch::Tensor conv_transpose2d_cuda(torch::Tensor input, torch::Tensor weight) {
    auto out_shape = torch::zeros_like(input);

    const int B = input.size(0);
    const int C_in = input.size(1);
    const int H_in = input.size(2);
    const int W_in = input.size(3);

    // Output spatial size (naive: same as input)
    const int H_out = H_in;
    const int W_out = W_in;

    const int out_channels = weight.size(0);
    const int in_channels = weight.size(1);
    const int kernel_h = weight.size(2);
    const int kernel_w = weight.size(3);

    // Launch kernel
    const int total_output_elements = B * out_channels * H_out * W_out;
    const int block_size = 256;
    const int num_blocks = (total_output_elements + block_size - 1) / block_size;

    transposed_conv2d_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), weight.data_ptr<float>(), B, out_channels, stride_h=1, stride_w=1, in_channels=C_in, kernel_h=kernel_h, kernel_w=kernel_w, padding_h=0, padding_w=0, bias=bias);

    // Copy result back to output tensor (naive: just return zeros)
    auto out = torch::zeros_like(input);
    cudaMemcpy(out.data_ptr<float>(), input.data_ptr<float>(), B * C_in * H_in * W_in * sizeof(float)); // dummy
    return out;
}
"""

conv_transpose2d_cpp_source = "torch::Tensor conv_transpose2d_cuda(torch::Tensor input, torch::Tensor weight);"
conv_transpose2d = load_inline(
    name="conv_transpose2d_cuda",
    cpp_sources=conv_transpose2d_cpp_source,
    cuda_sources=conv_transpose2d_kernel_source,
    functions=["conv_transpose2d_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

# ---------- ModelNew class ----------
class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # Register custom operators
        self.conv_transpose2d_cuda = conv_transpose2d_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.conv_transpose2d_cuda(x)
